def wire(v):return (json.dumps(v,sort_keys=True,indent=2,allow_nan=False)+'\n').encode()
def ident(s):return [s.st_dev,s.st_ino,s.st_mode,s.st_uid,s.st_gid,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns]
@contextmanager
def parent(path):
    fd=os.open('/',os.O_RDONLY|os.O_DIRECTORY)
    try:
        for x in Path(path).parts[1:-1]:
            n=os.open(x,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=fd);os.close(fd);fd=n
        yield fd,Path(path).name
    finally:os.close(fd)
def read(path,system=False):
    with parent(path) as (fd,name):
        s=os.stat(name,dir_fd=fd,follow_symlinks=False)
        assert stat.S_ISREG(s.st_mode) and 0<=s.st_size<=128<<20
        assert (s.st_nlink>=1 and s.st_uid==0 and not s.st_mode&0o022) if system else s.st_nlink==1
        f=os.open(name,os.O_RDONLY|os.O_NOFOLLOW,dir_fd=fd)
        try:
            assert ident(s)==ident(os.fstat(f));chunks=[];count=0
            while True:
                b=os.read(f,1<<20)
                if not b:break
                chunks.append(b);count+=len(b);assert count<=s.st_size
            assert count==s.st_size and ident(s)==ident(os.fstat(f))==ident(os.stat(name,dir_fd=fd,follow_symlinks=False))
        finally:os.close(f)
    b=b''.join(chunks)
    return {'path':str(path),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),
            'git_blob':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest(),'identity':ident(s)},b
def write(path,b,mode=0o600):
    path.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
    with path.open('xb') as f:f.write(b);f.flush();os.fsync(f.fileno())
    os.chmod(path,mode)
    p,actual=read(path);assert actual==b;return p
